{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Tobramycin, a structurally related aminoglycoside, showed very low or unmeasurable CSF concentrations in neonates after systemic administration, indicating that this polar polycationic class does not achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Whole-body autoradiography after IV administration of F-TAC, a tobramycin-derived aminoglycoside, showed rapid distribution to all tissues except brain and other nervous tissues, directly demonstrating lack of CNS penetration for aminoglycoside-like polycations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Kanamycin was reported to appear in CSF in proportion to blood concentrations, providing qualitative evidence of some aminoglycoside transfer across the BBB, but this does not establish adequate exposure and is outweighed by the more quantitative tobramycin and F-TAC failures.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Streptomycin is a large, highly polar, polycationic aminoglycoside with multiple guanidine groups and an extremely unfavorable passive-diffusion profile. Direct aminoglycoside evidence (tobramycin, F-TAC) shows negligible CNS/CSF exposure after systemic dosing, and meningitis-related BBB disruption is unlikely to overcome this physicochemical barrier sufficiently for meaningful CNS access.",
  "evidence_gaps": [
    "No direct streptomycin CSF or brain penetration measurement is present in the evidence set.",
    "Quantitative CSF/plasma ratios under meningitis conditions are not provided for the closest aminoglycoside analogues.",
    "Potential active uptake or efflux mechanisms at the BBB for this exact guanidinylated oligosaccharide are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

